effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  vec3 warm = vec3(1.08, 1.00, 0.88);
  vec3 g = c * mix(vec3(1.0), warm, warmth);
  g = clamp((g - 0.5) * contrast + 0.5, 0.0, 1.0);
  g = g * g * (3.0 - 2.0 * g);
  g = g + lift * (1.0 - g);
  vec3 col = mix(c, g, mixAmt);
  gl_FragColor = vec4(col * a, a);
}
